fn solve(input: Vec<char>) -> Vec<char> {
    // Make a mutable copy of the input
    let mut v = input;

    // Step 1: If the last character is a newline, drop it.
    if let Some(&last) = v.last() {
        if last == '\n' {
            v.pop();
        }
    }

    // A helper to recognize whitespace for the next trimming phase
    fn is_whitespace(c: char) -> bool {
        matches!(c, ' ' | '\t' | '\n' | '\r')
    }

    // Step 2: Trim whitespace from both ends
    let mut start = 0;
    let mut end = v.len();
    // Remove leading whitespace
    while start < end && is_whitespace(v[start]) {
        start += 1;
    }
    // Remove trailing whitespace
    while start < end && is_whitespace(v[end - 1]) {
        end -= 1;
    }
    // Get the trimmed slice
    let trimmed = &v[start..end];

    // Step 3: Check password validity
    // Conditions: length >= 5, at least one lowercase, one uppercase, and one digit
    let len_ok = trimmed.len() >= 5;
    let mut has_lower = false;
    let mut has_upper = false;
    let mut has_digit = false;
    for &c in trimmed {
        if ('a'..='z').contains(&c) {
            has_lower = true;
        } else if ('A'..='Z').contains(&c) {
            has_upper = true;
        } else if ('0'..='9').contains(&c) {
            has_digit = true;
        }
    }

    // Step 4: Produce the result
    let result_str = if len_ok && has_lower && has_upper && has_digit {
        "Correct\n"
    } else {
        "Too weak\n"
    };
    result_str.chars().collect()
}

